const row = $('PGSQL - Load Ecwid Catalog Sync Candidates').item.json;
const response = $json || {};
const sku = String(row.external_sku || '').trim();

if (response.error) {
  return {
    json: {
      ...row,
      ecwid_target_found: false,
      should_update: false,
      skip_reason: `Ecwid product lookup failed: ${response.error.message || response.error}`,
    },
  };
}

const items = Array.isArray(response.items) ? response.items : [];
let product = null;
let variation = null;

for (const candidate of items) {
  if (String(candidate?.sku || '').trim() === sku) {
    product = candidate;
    variation = null;
    break;
  }

  const exactVariation = Array.isArray(candidate?.variations)
    ? candidate.variations.find((entry) => String(entry?.sku || '').trim() === sku)
    : null;

  if (exactVariation) {
    product = candidate;
    variation = exactVariation;
    break;
  }
}

if (!product) {
  return {
    json: {
      ...row,
      ecwid_target_found: false,
      should_update: false,
      skip_reason: `No exact Ecwid product or variation found for SKU ${sku}`,
      ecwid_search_result_count: items.length,
    },
  };
}

const target = variation || product;
const ecwidUpcAttribute = Array.isArray(target?.attributes)
  ? target.attributes.find((entry) => String(entry?.name || '').trim().toUpperCase() === 'UPC')
  : null;

const targetUpc = String(ecwidUpcAttribute?.value || '').trim() || null;
const databaseUpc = String(row.upc || '').trim() || null;
const chosenUpc = databaseUpc || targetUpc || null;
const priceValue = Number(target?.price);
const categoryId = Array.isArray(product?.categoryIds) && product.categoryIds.length
  ? String(product.categoryIds[0])
  : null;

return {
  json: {
    ...row,
    ecwid_target_found: true,
    should_update: true,
    ecwid_product_id: product?.id != null ? String(product.id) : null,
    ecwid_variation_id: variation?.id != null ? String(variation.id) : null,
    ecwid_price: Number.isFinite(priceValue) ? priceValue : null,
    ecwid_url: product?.url ? String(product.url) : null,
    ecwid_category: categoryId,
    ecwid_target_upc: targetUpc,
    ecwid_upc: chosenUpc,
    needs_upc_reservation: !chosenUpc,
    needs_upc_write: Boolean(chosenUpc && !targetUpc),
    upc_mismatch: Boolean(databaseUpc && targetUpc && databaseUpc !== targetUpc),
    ecwid_search_result_count: items.length,
  },
};

const row = $('Code - Resolve Ecwid SKU Target').item.json;
const reservedUpc = String($json.reserved_upc || '').trim();

if (!reservedUpc) {
  throw new Error(`PostgreSQL did not reserve a UPC for ecommerce row ${row.ecommerce_id}`);
}

return {
  json: {
    ...row,
    ecwid_upc: reservedUpc,
    needs_upc_reservation: false,
    needs_upc_write: true,
  },
};

const quantity = Math.max(0, Math.trunc(Number($json.desired_quantity || 0)));
const productId = String($json.ecwid_product_id || '').trim();
const variationId = String($json.ecwid_variation_id || '').trim();

if (!productId) {
  throw new Error(`Ecwid product id is missing for ecommerce row ${$json.ecommerce_id}`);
}

const body = {
  quantity,
  unlimited: false,
};

if ($json.needs_upc_write && $json.ecwid_upc) {
  body.attributes = [
    {
      name: 'UPC',
      value: String($json.ecwid_upc),
    },
  ];
}

return {
  json: {
    ...$json,
    desired_quantity: quantity,
    update_url: variationId
      ? `https://app.ecwid.com/api/v3/${$env.ECWID_STORE_ID}/products/${productId}/combinations/${variationId}`
      : `https://app.ecwid.com/api/v3/${$env.ECWID_STORE_ID}/products/${productId}`,
    update_body: body,
  },
};

const row = $('Code - Prepare Ecwid Update').item.json;

const payload = {
  ecommerce_id: row.ecommerce_id,
  provider: 'ecwid',
  site_key: row.site_key || 'dank_mushrooms',
  external_sku: row.external_sku,
  external_product_id: row.ecwid_product_id || null,
  external_variation_id: row.ecwid_variation_id || null,
  external_category: row.ecwid_category || null,
  external_price: row.ecwid_price,
  external_stock: row.desired_quantity,
  public_url: row.ecwid_url || null,
  upc: row.ecwid_upc || null,
};

return {
  json: {
    ecommerce_id: row.ecommerce_id,
    external_sku: row.external_sku,
    desired_quantity: row.desired_quantity,
    upc_mismatch: row.upc_mismatch === true,
    payload_base64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
  },
};

return {
  json: {
    sync_status: 'skipped',
    ecommerce_id: $json.ecommerce_id,
    external_sku: $json.external_sku,
    reason: $json.skip_reason || 'Ecwid target not found',
  },
};
